{
  "name": "SPEC服务器客户端",
  "name_en": "SPEC Server Client",
  "manufacturer": "",
  "description": "用于连接实验站 SPEC 服务器的非实体软件组件。它可向远程 SPEC 会话发送命令、切换和创建目录、访问变量/电机/计数器对象，并等待系统就绪或计数完成，常用于束线或实验控制流程中的自动化脚本协调。",
  "description_en": "A non-physical software component for connecting to a beamline SPEC server. It sends commands to a remote SPEC session, changes or creates directories, accesses variables, motors, and counters, and waits for readiness or counting to complete. It is typically used to coordinate experiment automation workflows.",
  "actions": [
    {
      "action_name": "auto-run_cmd",
      "description": "在远程 SPEC 服务器上执行命令。",
      "description_en": "Execute a command on the remote SPEC server."
    },
    {
      "action_name": "auto-cd",
      "description": "切换 SPEC 侧的工作目录。",
      "description_en": "Change the working directory on the SPEC side."
    },
    {
      "action_name": "auto-mkdir",
      "description": "在 SPEC 侧创建目录。",
      "description_en": "Create a directory on the SPEC side."
    },
    {
      "action_name": "auto-get_variable",
      "description": "获取指定名称的 SPEC 变量。",
      "description_en": "Get a SPEC variable by name."
    },
    {
      "action_name": "auto-get_motor",
      "description": "获取指定名称的 SPEC 电机对象。",
      "description_en": "Get a SPEC motor object by name."
    },
    {
      "action_name": "auto-get_counter",
      "description": "获取指定名称的 SPEC 计数器对象。",
      "description_en": "Get a SPEC counter object by name."
    },
    {
      "action_name": "auto-block_for_ready",
      "description": "等待 SPEC 服务器进入就绪状态。",
      "description_en": "Wait for the SPEC server to become ready."
    },
    {
      "action_name": "auto-block_for_count",
      "description": "等待计数操作完成。",
      "description_en": "Wait for a counting operation to finish."
    },
    {
      "action_name": "auto-count",
      "description": "启动一次指定时间或监视计数的计数操作。",
      "description_en": "Start a count for a specified time or monitor count."
    }
  ],
  "tag_hints": [
    "SPEC server",
    "beamline control",
    "experiment automation",
    "remote command execution",
    "motor and counter access",
    "count synchronization",
    "scientific data acquisition"
  ]
}

